"use client";

import { type CSSProperties, type HTMLAttributes, type ReactNode, useMemo, useState } from "react";
import { donutSegments } from "../utils/chart";
import { cx } from "../utils/cx";

export type DonutDatum = { label: string; value: number };

export type DonutChartProps = Omit<HTMLAttributes<HTMLElement>, "title"> & {
  data: DonutDatum[];
  title: ReactNode;
  /** The figure in the middle when nothing is active (a total). Default: the sum. */
  center?: ReactNode;
  format?: Intl.NumberFormatOptions;
  locale?: string;
  empty?: ReactNode;
};

/**
 * A donut with a legend. Each slice and legend row is a button: hovering or focusing either highlights both and puts
 * its label, value and share in the middle. Series colors come from the `--hm-series-*` tokens.
 */
export function DonutChart({
  data,
  title,
  center,
  format,
  locale,
  empty = "No data.",
  className,
  ...rest
}: DonutChartProps) {
  const [active, setActive] = useState<number | null>(null);
  const fmt = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  const pct = useMemo(() => new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 }), [locale]);
  const segs = useMemo(
    () =>
      donutSegments(
        data.map((d) => d.value),
        1.2,
      ),
    [data],
  );
  const total = data.reduce((s, d) => s + Math.max(0, d.value), 0);
  const on = active === null ? null : data[active];
  return (
    <figure {...rest} className={cx("hm-donut", className)}>
      <figcaption className="hm-bar-chart-title">{title}</figcaption>
      {total > 0 ? (
        <div className="hm-donut-body">
          <div className="hm-donut-ring" onPointerLeave={() => setActive(null)}>
            <svg viewBox="0 0 36 36" aria-hidden="true">
              <circle className="hm-donut-track" cx="18" cy="18" r="14.5" />
              {segs.map((s, i) => (
                <circle
                  key={data[i]?.label}
                  className="hm-donut-seg"
                  cx="18"
                  cy="18"
                  r="14.5"
                  pathLength={100}
                  strokeDasharray={`${s.length} ${100 - s.length}`}
                  strokeDashoffset={-s.start}
                  data-on={active === i ? "" : undefined}
                  data-dim={active !== null && active !== i ? "" : undefined}
                  style={{ "--_c": `var(--hm-series-${(i % 6) + 1})`, "--hm-i": i } as CSSProperties}
                />
              ))}
            </svg>
            <div className="hm-donut-center" aria-live="polite">
              {on ? (
                <>
                  <span className="hm-donut-value">{pct.format((on.value || 0) / total)}</span>
                  <span className="hm-donut-label">{on.label}</span>
                </>
              ) : (
                <>
                  <span className="hm-donut-value">{center ?? fmt.format(total)}</span>
                  <span className="hm-donut-label">Total</span>
                </>
              )}
            </div>
          </div>
          <ul className="hm-donut-legend">
            {data.map((d, i) => (
              <li key={d.label}>
                <button
                  type="button"
                  className="hm-donut-item"
                  data-on={active === i ? "" : undefined}
                  style={{ "--_c": `var(--hm-series-${(i % 6) + 1})` } as CSSProperties}
                  onPointerEnter={() => setActive(i)}
                  onPointerLeave={() => setActive(null)}
                  onFocus={() => setActive(i)}
                  onBlur={() => setActive(null)}
                >
                  <span className="hm-donut-swatch" aria-hidden="true" />
                  <span className="hm-donut-name">{d.label}</span>
                  <span className="hm-donut-amount">{fmt.format(d.value)}</span>
                  <span className="hm-donut-pct">{pct.format(d.value / total)}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <p className="hm-empty">{empty}</p>
      )}
    </figure>
  );
}
